const FQ=[{q:"¿Cuánto cuesta una certificación de ingresos?",a:"Desde $80.000 COP según rango de ingresos. Incluye revisión, elaboración y firma por CP."},{q:"¿Cuánto tarda la entrega del certificado?",a:"Con documentación completa y pago confirmado, en horas."},{q:"¿Qué soportes necesito para la certificación?",a:"Depende del tipo de ingreso: nómina (laboral), facturas (independiente), contratos (arriendos), certificados (inversiones)."},{q:"¿La certificación tiene vigencia?",a:"30 a 60 días según la entidad destino."},{q:"¿Puedo solicitar si soy independiente?",a:"Sí. Certificamos ingresos de independientes, freelancers y contratistas."},{q:"¿Qué pasa si mis soportes están incompletos?",a:"Puede solicitar ahora y enviar soportes después por WhatsApp."},{q:"¿Cómo sé si debo declarar renta?",a:"Use nuestra herramienta en la sección Herramientas para verificar al instante."},{q:"¿Qué documentos para declarar renta?",a:"Formulario 220, extractos bancarios, certificados de inversiones, bienes, deudas y aportes."},{q:"¿Qué pasa si no declaro a tiempo?",a:"Sanción 5% por mes (art. 641-642 ET). Mínima $524.000."},{q:"¿Puedo corregir mi declaración?",a:"Sí, dentro de los plazos legales. Sanción por corrección del 10% si aumenta el impuesto."},{q:"¿Cómo funciona el plan mensual?",a:"Elegimos el plan según su empresa y nos encargamos de todo de forma permanente."},{q:"¿Puedo contratar un servicio puntual?",a:"Sí. Certificaciones, declaraciones, matrícula o creación de empresa sin plan mensual."},{q:"¿Qué incluye el outsourcing contable?",a:"Registro, conciliaciones, estados financieros, declaraciones, asesoría y cumplimiento NIIF."},{q:"¿Cuánto tarda renovar matrícula?",a:"1 a 3 días hábiles con documentación completa."},{q:"¿Qué necesito para crear empresa?",a:"Documento de identidad, tipo societario, nombre verificado en RUES, capital y objeto social."},{q:"¿Me ayudan con facturación electrónica?",a:"Sí. Habilitación DIAN, proveedor tecnológico, numeración y capacitación."},{q:"¿Qué medios de pago aceptan?",a:"Wompi: tarjeta, PSE, Nequi, Daviplata. También transferencia bancaria."},{q:"¿Cómo envío mis documentos?",a:"En el formulario (máx 10MB) o por WhatsApp al +57 301 310 1050."},{q:"¿Mis datos están seguros?",a:"Sí. Ley 1581/2012. Medidas técnicas, humanas y administrativas de protección."},{q:"¿Qué es la información exógena?",a:"Medios magnéticos: reporte de operaciones con terceros ante la DIAN. Sanciones por incumplimiento."}];
